def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    opp_d = 0
    for me, opp in history:
        if opp == 'C':
            opp_c += 1
        else:
            opp_d += 1

    c_c = 0
    c_d = 0
    d_c = 0
    d_d = 0
    for i in range(1, n):
        prev_me = history[i - 1][0]
        current_opp = history[i][1]
        if prev_me == 'C':
            if current_opp == 'C':
                c_c += 1
            else:
                c_d += 1
        else:
            if current_opp == 'C':
                d_c += 1
            else:
                d_d += 1

    recent_start = max(1, n - 10)
    rec_c_c = 0
    rec_c_d = 0
    for i in range(recent_start, n):
        prev_me = history[i - 1][0]
        current_opp = history[i][1]
        if prev_me == 'C':
            if current_opp == 'C':
                rec_c_c += 1
            else:
                rec_c_d += 1

    if opp_c == 0:
        return 'D'

    # If we have already learned that cooperation after our defection is
    # repeatable, exploit it when the opponent is not currently showing badness.
    if d_c >= 2 and d_d == 0 and last_opp == 'C' and rec_c_d <= rec_c_c:
        return 'D'

    # Opponent's defection is often a delayed response to our own defection.
    # Cooperate once to let a copy-based strategy catch up.
    if last_opp == 'D' and last_me == 'C' and n >= 2 and history[-2][0] == 'D':
        if rec_c_d >= 4 and rec_c_d > rec_c_c:
            return 'D'
        return 'C'

    # If the opponent tends to defect even when we cooperate, punish.
    if rec_c_d >= 3 and rec_c_d > rec_c_c:
        return 'D'

    # Estimate next opponent cooperation given our last action.
    pC = (c_c + 2.0) / (c_c + c_d + 3.0)
    pD = (d_c + 0.3) / (d_c + d_d + 3.0)

    rem = 100 - n
    if rem <= 0:
        return 'D'

    vc = [0.0] * (rem + 1)
    vd = [0.0] * (rem + 1)
    margin = 0.2

    for r in range(1, rem + 1):
        vCprev = vc[r - 1]
        vDprev = vd[r - 1]

        c_coop = 3.0 * pC + vCprev
        c_defect = 1.0 + 4.0 * pC + vDprev
        vc[r] = c_defect if c_defect > c_coop + margin else c_coop

        d_coop = 3.0 * pD + vCprev
        d_defect = 1.0 + 4.0 * pD + vDprev
        vd[r] = d_defect if d_defect > d_coop + margin else d_coop

    if last_me == 'C':
        q = pC
    else:
        q = pD

    now_c = 3.0 * q + vc[rem - 1]
    now_d = 1.0 + 4.0 * q + vd[rem - 1]

    return 'D' if now_d > now_c + margin else 'C'
